const REPO = 'cone97218-alt/thememanger';
const BRANCH = 'main';
const FILE = 'dist/theme-companion.js';

(async () => {
  const fetchWithTimeout = async (url, ms = 6000) => {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), ms);
    try {
      const res = await fetch(url, { cache: 'no-store', signal: ctrl.signal });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return res;
    } finally {
      clearTimeout(timer);
    }
  };

  let ref = BRANCH;
  try {
    const meta = await fetchWithTimeout(
      `https://api.github.com/repos/${REPO}/commits/${BRANCH}?t=${Date.now()}`,
      4000
    ).then((r) => r.json());
    if (meta && typeof meta.sha === 'string' && meta.sha.length >= 7) {
      ref = meta.sha;
    }
  } catch (_) {}

  const urls = [
    `https://raw.githubusercontent.com/${REPO}/${ref}/${FILE}`,
    `https://fastly.jsdelivr.net/gh/${REPO}@${ref}/${FILE}`,
    `https://cdn.jsdelivr.net/gh/${REPO}@${ref}/${FILE}`,
    `https://gcore.jsdelivr.net/gh/${REPO}@${ref}/${FILE}`,
  ];

  let code = '';
  let loadedUrl = '';
  for (const url of urls) {
    try {
      const res = await fetchWithTimeout(url, 8000);
      const text = await res.text();
      if (text && text.length > 1000) {
        code = text;
        loadedUrl = url;
        break;
      }
    } catch (_) {}
  }

  if (!code) {
    console.error('[ThemeCompanion Loader] 所有镜像均拉取失败');
    return;
  }

  try {
    (0, eval)(code);
    console.log(`[ThemeCompanion Loader] 已加载 (${ref.slice(0, 7)}) ← ${loadedUrl}`);
  } catch (err) {
    console.error('[ThemeCompanion Loader] 脚本执行失败:', err);
  }
})();
